export interface ConnectorConfig {
  /** Trello API key from TRELLO_API_KEY env var */
  trelloApiKey: string;
  /** Trello token from TRELLO_TOKEN env var */
  trelloToken: string;
  /** Trello list ID where the target card resides */
  trelloListId: string;
  /** Optional: name of the checklist to create (default: "Attendee Info") */
  checklistName?: string;
  /** Optional: maximum retry attempts for 429 responses (default: 3) */
  maxRetries?: number;
  /** Optional: base delay in ms for exponential backoff (default: 1000) */
  baseRetryDelayMs?: number;
  /** Optional: injected fetch for testing */
  fetch?: typeof fetch;
}

export interface CalendarEventPayload {
  event: string;
  webhook_name: string;
  account_id: string;
  id: string;
  calendar_id: string;
  created_at: string;
  updated_at: string;
  title: string;
  attendees: Array<{
    email?: string;
    display_name?: string;
  }>;
  start: {
    date_time: string;
    time_zone: string;
  };
  end: {
    date_time: string;
    time_zone: string;
  };
}

export interface HandleResult {
  cardId: string;
  checklistId: string;
  checkItemId: string;
  attendeeValue: string;
}

interface TrelloCard {
  id: string;
  name: string;
  idList: string;
}

interface TrelloChecklist {
  id: string;
  name: string;
  idBoard: string;
  idCard: string;
}

interface TrelloCheckItem {
  id: string;
  name: string;
  state: string;
  idChecklist: string;
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch;
}

function buildUrlWithAuth(baseUrl: string, apiKey: string, token: string): string {
  const url = new URL(baseUrl);
  url.searchParams.set('key', apiKey);
  url.searchParams.set('token', token);
  return url.toString();
}

async function requestWithRetry(
  fetchFn: typeof fetch,
  url: string,
  init: RequestInit,
  maxRetries: number,
  baseDelayMs: number,
): Promise<Response> {
  let attempt = 0;
  while (true) {
    const response = await fetchFn(url, init);
    if (response.status !== 429 || attempt >= maxRetries) {
      return response;
    }
    const retryAfter = response.headers.get('retry-after');
    let delayMs: number;
    if (retryAfter) {
      const parsed = parseRetryAfter(retryAfter);
      delayMs = Number.isNaN(parsed) ? baseDelayMs * 2 ** attempt : parsed;
    } else {
      delayMs = baseDelayMs * 2 ** attempt;
    }
    await new Promise((resolve) => setTimeout(resolve, delayMs));
    attempt++;
  }
}

function parseRetryAfter(value: string): number {
  const seconds = Number.parseInt(value, 10);
  if (!Number.isNaN(seconds)) {
    return seconds * 1000;
  }
  const date = Date.parse(value);
  if (!Number.isNaN(date)) {
    return Math.max(0, date - Date.now());
  }
  return Number.NaN;
}

async function findCardInList(
  fetchFn: typeof fetch,
  listId: string,
  apiKey: string,
  token: string,
  cardName: string,
  maxRetries: number,
  baseDelayMs: number,
): Promise<TrelloCard> {
  const url = buildUrlWithAuth(
    `https://api.trello.com/1/lists/${encodeURIComponent(listId)}/cards`,
    apiKey,
    token,
  );
  const response = await requestWithRetry(fetchFn, url, { method: 'GET' }, maxRetries, baseDelayMs);
  if (!response.ok) {
    throw new Error(`Trello GET /lists/${listId}/cards failed: ${response.status} ${response.statusText}`);
  }
  const data = (await response.json()) as { cards: TrelloCard[] };
  const card = data.cards.find((c) => c.name === cardName);
  if (!card) {
    throw new Error(`Card with name "${cardName}" not found in list ${listId}`);
  }
  return card;
}

async function createChecklist(
  fetchFn: typeof fetch,
  cardId: string,
  checklistName: string,
  apiKey: string,
  token: string,
  maxRetries: number,
  baseDelayMs: number,
): Promise<TrelloChecklist> {
  const url = buildUrlWithAuth('https://api.trello.com/1/checklists', apiKey, token);
  const body = JSON.stringify({ name: checklistName, idCard: cardId });
  const response = await requestWithRetry(
    fetchFn,
    url,
    { method: 'POST', headers: { 'Content-Type': 'application/json' }, body },
    maxRetries,
    baseDelayMs,
  );
  if (!response.ok) {
    throw new Error(`Trello POST /checklists failed: ${response.status} ${response.statusText}`);
  }
  return (await response.json()) as TrelloChecklist;
}

async function addChecklistItem(
  fetchFn: typeof fetch,
  checklistId: string,
  itemName: string,
  apiKey: string,
  token: string,
  maxRetries: number,
  baseDelayMs: number,
): Promise<TrelloCheckItem> {
  const url = buildUrlWithAuth(
    `https://api.trello.com/1/checklists/${encodeURIComponent(checklistId)}/checkItems`,
    apiKey,
    token,
  );
  const body = JSON.stringify({ name: itemName, checked: false });
  const response = await requestWithRetry(
    fetchFn,
    url,
    { method: 'POST', headers: { 'Content-Type': 'application/json' }, body },
    maxRetries,
    baseDelayMs,
  );
  if (!response.ok) {
    throw new Error(`Trello POST /checklists/${checklistId}/checkItems failed: ${response.status} ${response.statusText}`);
  }
  return (await response.json()) as TrelloCheckItem;
}

export async function handle(
  payload: CalendarEventPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  if (!payload.event || payload.event !== 'calendar_event_created') {
    throw new Error('Payload event must be "calendar_event_created"');
  }
  if (!payload.attendees || payload.attendees.length === 0) {
    throw new Error('Payload must contain at least one attendee');
  }
  const firstAttendee = payload.attendees[0];
  const attendeeValue = firstAttendee.email ?? firstAttendee.display_name;
  if (!attendeeValue) {
    throw new Error('First attendee must have either email or display_name');
  }
  if (!config.trelloApiKey) {
    throw new Error('Config trelloApiKey is required');
  }
  if (!config.trelloToken) {
    throw new Error('Config trelloToken is required');
  }
  if (!config.trelloListId) {
    throw new Error('Config trelloListId is required');
  }

  const fetchFn = getFetch(config);
  const maxRetries = config.maxRetries ?? 3;
  const baseDelayMs = config.baseRetryDelayMs ?? 1000;
  const checklistName = config.checklistName ?? 'Attendee Info';

  const card = await findCardInList(
    fetchFn,
    config.trelloListId,
    config.trelloApiKey,
    config.trelloToken,
    payload.title,
    maxRetries,
    baseDelayMs,
  );

  const checklist = await createChecklist(
    fetchFn,
    card.id,
    checklistName,
    config.trelloApiKey,
    config.trelloToken,
    maxRetries,
    baseDelayMs,
  );

  const checkItem = await addChecklistItem(
    fetchFn,
    checklist.id,
    attendeeValue,
    config.trelloApiKey,
    config.trelloToken,
    maxRetries,
    baseDelayMs,
  );

  return {
    cardId: card.id,
    checklistId: checklist.id,
    checkItemId: checkItem.id,
    attendeeValue,
  };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, CalendarEventPayload } from './connector';
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  type RecordedCall,
} from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      trelloApiKey: 'test-key',
      trelloToken: 'test-token',
      trelloListId: 'target-list-id',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as CalendarEventPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.cardId).toBe('5f5f5f5f5f5f5f5f5f5f5f5f');
    expect(result.checklistId).toBe('5f5f5f5f5f5f5f5f5f5f5f5g');
    expect(result.checkItemId).toBe('5f5f5f5f5f5f5f5f5f5f5f5i');
    expect(result.attendeeValue).toBe('customer@example.com');
  });
});

describe('handle', () => {
  it('validates required event type', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200));
    const payload = { ...SOURCE_EXAMPLE, event: 'other_event' } as CalendarEventPayload;
    const config: ConnectorConfig = {
      trelloApiKey: 'k',
      trelloToken: 't',
      trelloListId: 'list',
      fetch,
    };
    await expect(handle(payload, config)).rejects.toThrow('Payload event must be "calendar_event_created"');
    expect(calls.length).toBe(0);
  });

  it('validates at least one attendee', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200));
    const payload = { ...SOURCE_EXAMPLE, attendees: [] } as CalendarEventPayload;
    const config: ConnectorConfig = {
      trelloApiKey: 'k',
      trelloToken: 't',
      trelloListId: 'list',
      fetch,
    };
    await expect(handle(payload, config)).rejects.toThrow('Payload must contain at least one attendee');
    expect(calls.length).toBe(0);
  });

  it('validates attendee has email or display_name', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200));
    const payload = { ...SOURCE_EXAMPLE, attendees: [{}] } as CalendarEventPayload;
    const config: ConnectorConfig = {
      trelloApiKey: 'k',
      trelloToken: 't',
      trelloListId: 'list',
      fetch,
    };
    await expect(handle(payload, config)).rejects.toThrow('First attendee must have either email or display_name');
    expect(calls.length).toBe(0);
  });

  it('validates required config fields', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200));
    const config = { trelloApiKey: '', trelloToken: 't', trelloListId: 'list', fetch } as ConnectorConfig;
    await expect(handle(SOURCE_EXAMPLE as unknown as CalendarEventPayload, config)).rejects.toThrow('Config trelloApiKey is required');
    expect(calls.length).toBe(0);
  });

  it('uses display_name when email is missing', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/lists/target-list-id/cards')) {
        return jsonResponse({ cards: [{ id: 'card-1', name: 'Meeting with customer', idList: 'target-list-id' }] });
      }
      if (req.url === 'https://api.trello.com/1/checklists') {
        return jsonResponse({ id: 'checklist-1', name: 'Attendee Info', idBoard: 'board-1', idCard: 'card-1' });
      }
      if (req.url.includes('/checklists/checklist-1/checkItems')) {
        return jsonResponse({ id: 'item-1', name: 'Customer Name', state: 'incomplete', idChecklist: 'checklist-1' });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const payload = {
      ...SOURCE_EXAMPLE,
      attendees: [{ display_name: 'Customer Name' }],
    } as CalendarEventPayload;
    const config: ConnectorConfig = {
      trelloApiKey: 'k',
      trelloToken: 't',
      trelloListId: 'target-list-id',
      fetch,
    };
    const result = await handle(payload, config);
    expect(result.attendeeValue).toBe('Customer Name');
    expect(calls.length).toBe(3);
    const checkItemCall = calls[2];
    expect(checkItemCall.json).toEqual({ name: 'Customer Name', checked: false });
  });

  it('throws on non-2xx response from Trello', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401));
    const config: ConnectorConfig = {
      trelloApiKey: 'k',
      trelloToken: 't',
      trelloListId: 'list',
      fetch,
    };
    await expect(handle(SOURCE_EXAMPLE as unknown as CalendarEventPayload, config)).rejects.toThrow(
      'Trello GET /lists/list/cards failed: 401 Unauthorized',
    );
    expect(calls.length).toBe(1);
  });

  it('retries on 429 and succeeds on second attempt', async () => {
    let attempt = 0;
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/lists/target-list-id/cards')) {
        if (attempt === 0) {
          attempt++;
          return jsonResponse({ error: 'Too Many Requests' }, 429);
        }
        return jsonResponse({ cards: [{ id: 'card-1', name: 'Meeting with customer', idList: 'target-list-id' }] });
      }
      if (req.url === 'https://api.trello.com/1/checklists') {
        return jsonResponse({ id: 'checklist-1', name: 'Attendee Info', idBoard: 'board-1', idCard: 'card-1' });
      }
      if (req.url.includes('/checklists/checklist-1/checkItems')) {
        return jsonResponse({ id: 'item-1', name: 'customer@example.com', state: 'incomplete', idChecklist: 'checklist-1' });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config: ConnectorConfig = {
      trelloApiKey: 'k',
      trelloToken: 't',
      trelloListId: 'target-list-id',
      maxRetries: 3,
      baseRetryDelayMs: 10,
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as CalendarEventPayload, config);
    expect(result.cardId).toBe('card-1');
    expect(calls.length).toBe(4); // 2 GET cards (1 retry) + 1 POST checklist + 1 POST checkItem
  });

  it('exhausts retries and throws on persistent 429', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Too Many Requests' }, 429));
    const config: ConnectorConfig = {
      trelloApiKey: 'k',
      trelloToken: 't',
      trelloListId: 'list',
      maxRetries: 2,
      baseRetryDelayMs: 10,
      fetch,
    };
    await expect(handle(SOURCE_EXAMPLE as unknown as CalendarEventPayload, config)).rejects.toThrow(
      'Trello GET /lists/list/cards failed: 429 Too Many Requests',
    );
    expect(calls.length).toBe(3); // initial + 2 retries
  });

  it('parses Retry-After header as seconds', async () => {
    let attempt = 0;
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/lists/target-list-id/cards')) {
        if (attempt === 0) {
          attempt++;
          const res = jsonResponse({ error: 'Too Many Requests' }, 429);
          res.headers.set('retry-after', '1');
          return res;
        }
        return jsonResponse({ cards: [{ id: 'card-1', name: 'Meeting with customer', idList: 'target-list-id' }] });
      }
      if (req.url === 'https://api.trello.com/1/checklists') {
        return jsonResponse({ id: 'checklist-1', name: 'Attendee Info', idBoard: 'board-1', idCard: 'card-1' });
      }
      if (req.url.includes('/checklists/checklist-1/checkItems')) {
        return jsonResponse({ id: 'item-1', name: 'customer@example.com', state: 'incomplete', idChecklist: 'checklist-1' });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config: ConnectorConfig = {
      trelloApiKey: 'k',
      trelloToken: 't',
      trelloListId: 'target-list-id',
      maxRetries: 3,
      baseRetryDelayMs: 1000,
      fetch,
    };
    await handle(SOURCE_EXAMPLE as unknown as CalendarEventPayload, config);
    expect(calls.length).toBe(4);
  });

  it('parses Retry-After header as HTTP date', async () => {
    let attempt = 0;
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/lists/target-list-id/cards')) {
        if (attempt === 0) {
          attempt++;
          const res = jsonResponse({ error: 'Too Many Requests' }, 429);
          const future = new Date(Date.now() + 50).toUTCString();
          res.headers.set('retry-after', future);
          return res;
        }
        return jsonResponse({ cards: [{ id: 'card-1', name: 'Meeting with customer', idList: 'target-list-id' }] });
      }
      if (req.url === 'https://api.trello.com/1/checklists') {
        return jsonResponse({ id: 'checklist-1', name: 'Attendee Info', idBoard: 'board-1', idCard: 'card-1' });
      }
      if (req.url.includes('/checklists/checklist-1/checkItems')) {
        return jsonResponse({ id: 'item-1', name: 'customer@example.com', state: 'incomplete', idChecklist: 'checklist-1' });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config: ConnectorConfig = {
      trelloApiKey: 'k',
      trelloToken: 't',
      trelloListId: 'target-list-id',
      maxRetries: 3,
      baseRetryDelayMs: 1000,
      fetch,
    };
    await handle(SOURCE_EXAMPLE as unknown as CalendarEventPayload, config);
    expect(calls.length).toBe(4);
  });

  it('falls back to exponential backoff when Retry-After is malformed', async () => {
    let attempt = 0;
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/lists/target-list-id/cards')) {
        if (attempt === 0) {
          attempt++;
          const res = jsonResponse({ error: 'Too Many Requests' }, 429);
          res.headers.set('retry-after', 'not-a-number');
          return res;
        }
        return jsonResponse({ cards: [{ id: 'card-1', name: 'Meeting with customer', idList: 'target-list-id' }] });
      }
      if (req.url === 'https://api.trello.com/1/checklists') {
        return jsonResponse({ id: 'checklist-1', name: 'Attendee Info', idBoard: 'board-1', idCard: 'card-1' });
      }
      if (req.url.includes('/checklists/checklist-1/checkItems')) {
        return jsonResponse({ id: 'item-1', name: 'customer@example.com', state: 'incomplete', idChecklist: 'checklist-1' });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config: ConnectorConfig = {
      trelloApiKey: 'k',
      trelloToken: 't',
      trelloListId: 'target-list-id',
      maxRetries: 3,
      baseRetryDelayMs: 10,
      fetch,
    };
    await handle(SOURCE_EXAMPLE as unknown as CalendarEventPayload, config);
    expect(calls.length).toBe(4);
  });

  it('uses custom checklist name from config', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/lists/target-list-id/cards')) {
        return jsonResponse({ cards: [{ id: 'card-1', name: 'Meeting with customer', idList: 'target-list-id' }] });
      }
      if (req.url === 'https://api.trello.com/1/checklists') {
        const body = req.json as { name: string };
        expect(body.name).toBe('Custom Checklist');
        return jsonResponse({ id: 'checklist-1', name: 'Custom Checklist', idBoard: 'board-1', idCard: 'card-1' });
      }
      if (req.url.includes('/checklists/checklist-1/checkItems')) {
        return jsonResponse({ id: 'item-1', name: 'customer@example.com', state: 'incomplete', idChecklist: 'checklist-1' });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config: ConnectorConfig = {
      trelloApiKey: 'k',
      trelloToken: 't',
      trelloListId: 'target-list-id',
      checklistName: 'Custom Checklist',
      fetch,
    };
    await handle(SOURCE_EXAMPLE as unknown as CalendarEventPayload, config);
    expect(calls.length).toBe(3);
  });

  it('throws when card not found in list', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/lists/target-list-id/cards')) {
        return jsonResponse({ cards: [{ id: 'other-card', name: 'Other Card', idList: 'target-list-id' }] });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config: ConnectorConfig = {
      trelloApiKey: 'k',
      trelloToken: 't',
      trelloListId: 'target-list-id',
      fetch,
    };
    await expect(handle(SOURCE_EXAMPLE as unknown as CalendarEventPayload, config)).rejects.toThrow(
      'Card with name "Meeting with customer" not found in list target-list-id',
    );
    expect(calls.length).toBe(1);
  });
});

