export interface DocumentedEndpoint {
  method: string
  /** As documented; may contain placeholders such as {id}, :id, <id> or a region host like usX. */
  url: string
  response: unknown
}

/** Target endpoints the connector may call, in the documented order, with their documented responses. */
export const TARGET_ENDPOINTS: DocumentedEndpoint[] = [
  {
    "method": "GET",
    "url": "https://api.trello.com/1/lists/{idList}/cards",
    "response": {
      "cards": [
        {
          "id": "5f5f5f5f5f5f5f5f5f5f5f5f",
          "name": "Existing Card Title",
          "idList": "target-list-id"
        }
      ]
    }
  },
  {
    "method": "POST",
    "url": "https://api.trello.com/1/checklists",
    "response": {
      "id": "5f5f5f5f5f5f5f5f5f5f5f5g",
      "name": "Attendee Info",
      "idBoard": "5f5f5f5f5f5f5f5f5f5f5f5h",
      "idCard": "5f5f5f5f5f5f5f5f5f5f5f5f"
    }
  },
  {
    "method": "POST",
    "url": "https://api.trello.com/1/checklists/{idChecklist}/checkItems",
    "response": {
