  it('uses custom checklist name from config', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/lists/target-list-id/cards') && req.method === 'GET') {
        return jsonResponse({ cards: [{ id: 'card-1', name: 'Meeting with customer', idList: 'target-list-id' }] });
      }
      // Checklist creation: POST to /checklists (not /checkItems)
      if (req.url.startsWith('https://api.trello.com/1/checklists?') && req.method === 'POST' && !req.url.includes('/checkItems')) {
        const body = req.json as { name: string };
        expect(body.name).toBe('Custom Checklist');
        return jsonResponse({ id: 'checklist-1', name: 'Custom Checklist', idBoard: 'board-1', idCard: 'card-1' });
      }
      // CheckItem creation: POST to /checklists/{id}/checkItems
      if (req.url.includes('/checklists/checklist-1/checkItems') && req.method === 'POST') {
        return jsonResponse({ id: 'item-1', name: 'customer@example.com', state: 'incomplete', idChecklist: 'checklist-1' });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config: ConnectorConfig = {
      trelloApiKey: 'k',
      trelloToken: 't',
      trelloListId: 'target-list-id',
      checklistName: 'Custom Checklist',
      fetch,
    };
    await handle(SOURCE_EXAMPLE as unknown as CalendarEventPayload, config);
    expect(calls.length).toBe(3);
  });

  it('throws when card not found in list and no fallback', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/lists/target-list-id/cards') && req.method === 'GET') {
        return jsonResponse({ cards: [] });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const config: ConnectorConfig = {
      trelloApiKey: 'k',
      trelloToken: 't',
      trelloListId: 'target-list-id',
      fetch,
    };
    await expect(handle(SOURCE_EXAMPLE as unknown as CalendarEventPayload, config)).rejects.toThrow(
      'Card with name "Meeting with customer" not found in list target-list-id and no fallback card available',
    );
    expect(calls.length).toBe(1);
  });
});

